function wowSections(){return `<section class="savour-scene" id="savour"><div class="savour-sticky"><div class="scene-grain" aria-hidden="true"></div><div class="scene-orbit orbit-one" aria-hidden="true"></div><div class="scene-orbit orbit-two" aria-hidden="true"></div><div class="scene-topline"><span>FEAST CATERING / THE ART OF GETTING TOGETHER</span><span class="scene-chapter">01 — SAVOUR THE MOMENT</span></div><figure class="scene-layer scene-sandwich" data-depth="110" data-turn="-9"><img src="/images/platter.jpg" width="900" height="1000" alt="Freshly filled sandwiches on a sharing platter" loading="lazy"><figcaption>A LITTLE GENEROSITY.</figcaption></figure><figure class="scene-layer scene-salad" data-depth="-140" data-turn="12"><img src="/images/salad.jpg" width="1000" height="1000" alt="A colourful salad with fresh vegetables" loading="lazy"><figcaption>A LITTLE COLOUR.</figcaption></figure><figure class="scene-layer scene-canapes" data-depth="75" data-turn="8"><img src="/images/canapes.jpg" width="1000" height="700" alt="Golden finger food with fresh garnishes" loading="lazy"><figcaption>A LOT TO LOOK FORWARD TO.</figcaption></figure><figure class="scene-layer scene-wrap" data-depth="-85" data-turn="-12"><img src="/images/wrap.jpg" width="700" height="800" alt="Filled wraps ready for sharing" loading="lazy"></figure><div class="scene-type"><span class="eyebrow">THE FOOD IS JUST THE BEGINNING</span><h2>Made to<br>bring us<br><em>together.</em></h2><p>The first bite. The shared stories.<br>The moments that stay with you.</p><a class="scene-link" href="/menu" data-route>Find your kind of feast <span>↗</span></a></div><span class="scene-star" aria-hidden="true">✳</span><div class="scene-bottomline"><span>GOOD FOOD HAS A WAY OF BRINGING PEOPLE CLOSER.</span><div><span>SCROLL TO SAVOUR</span><span class="scene-progress"><i></i></span></div></div></div></section>`}
function filmSection(){return `<section class="feast-film-section" id="feast-film"><div class="film-title reveal"><div><div class="eyebrow">A FEAST FOR THE SENSES</div><h2>You can almost<br><em>taste it.</em></h2></div><p>A finishing touch. A little anticipation.<br>Something delicious is taking shape.</p></div><div class="film-expand"><div class="film-frame"><video id="feast-film-video" muted loop playsinline preload="none" poster="/images/cooking-poster.jpg" aria-label="Cooking film showing a chef arranging small plates"></video><div class="film-vignette" aria-hidden="true"></div><button class="film-play" id="film-play" aria-label="Play cooking video"><span class="film-play-icon">▶</span><span class="film-button-label">Play film</span></button><div class="film-overline"><span>FEAST / THE LITTLE DETAILS</span><span>GOOD FOOD IN MOTION</span></div><div class="film-failure" id="film-status" role="status"></div></div></div><div class="film-caption"><span>THE LITTLE DETAILS. THE SHARED MOMENTS.</span><a href="/contact" data-route>Make your next occasion a feast <span>↗</span></a></div></section>`}
let clearWow=()=>{};
function initWow(){clearWow();const scene=document.querySelector('.savour-scene'),film=document.querySelector('#feast-film-video'),filmSectionEl=document.querySelector('.feast-film-section'),banner=document.querySelector('.sharing-banner');if(!scene&&!film)return;const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');let raf=0,active=true,videoVisible=false,videoUserPaused=false,loaded=false;const layers=scene?[...scene.querySelectorAll('[data-depth]')]:[];let button=document.querySelector('#film-play');let filmObserver=null;
const clamp=(n,min,max)=>Math.min(max,Math.max(min,n));
function noMotion(){return reduce.matches||document.body.classList.contains('motion-paused')}
function draw(){raf=0;if(!active)return;let vh=window.innerHeight;if(scene){let rect=scene.getBoundingClientRect();let travel=Math.max(1,scene.offsetHeight-vh);let p=clamp(-rect.top/travel,0,1);scene.style.setProperty('--savour-progress',p);if(rect.bottom>0&&rect.top<vh){layers.forEach(el=>{let depthScale=window.innerWidth<=700?.45:1;let y=noMotion()?0:(p-.5)*Number(el.dataset.depth)*depthScale;let rot=Number(el.dataset.turn)+(noMotion()?0:(p-.5)*5);el.style.transform=`translate3d(0,${y}px,0) rotate(${rot}deg)`});scene.querySelector('.scene-type').style.transform=noMotion()?'none':`translate3d(0,${(p-.5)*-30}px,0)`}}if(filmSectionEl){let r=filmSectionEl.getBoundingClientRect();let p=clamp((vh-r.top)/(vh*.9),0,1);filmSectionEl.style.setProperty('--film-reveal',noMotion()?1:p)}if(banner){let r=banner.getBoundingClientRect();if(r.bottom>0&&r.top<vh){let y=noMotion()?0:(r.top+r.height/2-vh/2)*.15;banner.style.setProperty('--banner-parallax',`${clamp(y,-65,65)}px`)}}}
function requestDraw(){if(!raf)raf=requestAnimationFrame(draw)}
function syncVideo(){if(!film||!button)return;const playing=!film.paused&&!film.ended;button.classList.toggle('is-playing',playing);button.setAttribute('aria-label',playing?'Pause cooking video':'Play cooking video');button.querySelector('.film-play-icon').textContent=playing?'Ⅱ':'▶';button.querySelector('.film-button-label').textContent=playing?'Pause film':'Play film'}
function startVideo(manual=false){if(!film||!film.isConnected)return;if(!loaded){film.src='/video/feast-cooking.mp4';loaded=true;film.load()}if(manual||(!noMotion()&&!videoUserPaused&&videoVisible)){film.play().catch(()=>{syncVideo()})}}
function toggleVideo(){if(!film)return;if(film.paused){videoUserPaused=false;startVideo(true)}else{videoUserPaused=true;film.pause()}}
function motionChanged(){requestDraw();if(film){if(noMotion())film.pause();else if(videoVisible&&!videoUserPaused)startVideo()}}
function onMetadata(){film.controls=true}
function failedVideo(){loaded=false;document.querySelector('#film-status').textContent='The film could not load. Press play to try again.';syncVideo()}
if(film){filmObserver=new IntersectionObserver(entries=>{for(const e of entries){videoVisible=e.isIntersecting;if(videoVisible){startVideo()}else film.pause()}},{threshold:.2});filmObserver.observe(film);button.addEventListener('click',toggleVideo);film.addEventListener('loadedmetadata',onMetadata);film.addEventListener('play',syncVideo);film.addEventListener('pause',syncVideo);film.addEventListener('error',failedVideo);film.addEventListener('playing',()=>{let status=document.querySelector('#film-status');if(status)status.textContent=''})}
const mutation=new MutationObserver(motionChanged);mutation.observe(document.body,{attributes:true,attributeFilter:['class']});reduce.addEventListener('change',motionChanged);window.addEventListener('scroll',requestDraw,{passive:true});window.addEventListener('resize',requestDraw,{passive:true});requestDraw();clearWow=()=>{active=false;if(raf)cancelAnimationFrame(raf);window.removeEventListener('scroll',requestDraw);window.removeEventListener('resize',requestDraw);reduce.removeEventListener('change',motionChanged);mutation.disconnect();filmObserver?.disconnect();if(film){film.pause();button?.removeEventListener('click',toggleVideo);film.removeEventListener('loadedmetadata',onMetadata);film.removeEventListener('play',syncVideo);film.removeEventListener('pause',syncVideo);film.removeEventListener('error',failedVideo)}}}
